-- ── 1. THE LESSER OFFICERS (world data) ──────────────────────────────────────────────────────
insert into public.officers (code, name, specialty, bonus_pct, wage_ducats, nation_id, home_port_id, blurb)
select v.code, v.name, v.specialty, v.bonus_pct, v.wage, n.id, p.id, v.blurb
  from (values
    ('NPCPILOTPRT', 'Gonçalo Pires', 'NAVIGATOR', 4, 600, 'PRT', 'OPO', 'A Porto pilot who knows the bar at Lisbon and every shoal of the Algarve.'),
    ('NPCPURSERESP', 'Diego de Arana', 'PURSER', 4.5, 620, 'ESP', 'BIL', 'A Basque factor who counts iron and wool in the same breath.'),
    ('NPCQMNLD', 'Pieter Hooft', 'QUARTERMASTER', 5, 680, 'NLD', 'MID', 'Stows a Zeeland hold so tight the cooper weeps.'),
    ('NPCSURGENG', 'Thomas Ward', 'SURGEON', 4, 560, 'ENG', 'PTH', 'Ship''s surgeon out of Portsmouth; lemons in every chest.'),
    ('NPCQMHAN', 'Hinrich Castorp', 'QUARTERMASTER', 4.5, 600, 'HAN', 'BER', 'Kept the Bryggen stores for the Kontor eleven winters.'),
    ('NPCPILOTGEN', 'Luca Spinola', 'NAVIGATOR', 4, 580, 'GEN', 'NAP', 'Knows the Tyrrhenian by its colours at dawn.'),
    ('NPCPURSERVEN', 'Marin Contarini', 'PURSER', 5, 700, 'VEN', 'DBR', 'Keeps the Muda''s books in the Rialto''s own hand.'),
    ('NPCSURGFRA', 'Jean Lambert', 'SURGEON', 4, 560, 'FRA', 'NAN', 'A Nantes barber-surgeon with a steady saw.'),
    ('NPCPILOTOTT', 'Seydi Ali', 'NAVIGATOR', 5, 690, 'OTT', 'ALE', 'Has sailed the Alexandria run since the reed beds were young.'),
    ('NPCPURSERMUG', 'Virji Vora', 'PURSER', 6, 800, 'MUG', 'SRT', 'The richest broker on the Surat waterfront lends to his own captains.'),
    ('NPCPILOTMNG', 'Lin Daoqian', 'NAVIGATOR', 4.5, 640, 'MNG', 'QUA', 'Reads the monsoon off the Zayton quays.'),
    ('NPCQMJPN', 'Suminokura Ryōi', 'QUARTERMASTER', 5, 660, 'JPN', 'NAG', 'Fits out red-seal ships for the southern seas.'))
       as v(code, name, specialty, bonus_pct, wage, nation, home, blurb)
  join public.nations n on n.code = v.nation
  join public.ports p on p.code = v.home;

